from collections import deque

def project(src, out, panels, top_end, bg):
    pred=[row[:] for row in src]
    # clear source zone to background
    for r in range(top_end):
        for c in range(len(src[0])):
            if src[r][c]!=bg: pred[r][c]=bg
    # components, only colors with panels
    H,W=len(src),len(src[0])
    for color,(bottom,edge) in panels.items():
        seen=set()
        for r in range(top_end):
          for c in range(W):
            if src[r][c]!=color or (r,c) in seen: continue
            comp=[]; q=[(r,c)]; seen.add((r,c))
            while q:
              rr,cc=q.pop(); comp.append((rr,cc))
              for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                if 0<=nr<top_end and 0<=nc<W and (nr,nc) not in seen and src[nr][nc]==color:
                  seen.add((nr,nc));q.append((nr,nc))
            shift=bottom-max(rr for rr,cc in comp)
            for rr,cc in comp:
              tr=rr+shift
              if tr<0 or tr>=H: raise ValueError((color,comp,shift))
              pred[tr][cc]=edge
    return pred
